java.io.File root = new java.io.File("path/to/repository");
org.machanism.machai.project.layout.ProjectLayout layout = org.machanism.machai.project.ProjectLayoutManager.detectProjectLayout(root);
for (java.lang.String source : layout.getSources()) {
    java.io.File sourceDirectory = new java.io.File(layout.getProjectDir(), source);
    System.out.println(sourceDirectory.getPath());
}

java.io.File repository = new java.io.File(args[0]);
org.machanism.machai.project.layout.ProjectLayout layout = org.machanism.machai.project.ProjectLayoutManager.detectProjectLayout(repository);
for (java.lang.String path : layout.getSources()) {
    System.out.println(new java.io.File(layout.getProjectDir(), path).getAbsolutePath());
}

java.io.File repositoryRoot = new java.io.File("workspace");
org.machanism.machai.project.layout.ProjectLayout layout = org.machanism.machai.project.ProjectLayoutManager.detectProjectLayout(repositoryRoot);
org.machanism.machai.project.ProjectProcessor processor = new org.machanism.machai.project.ProjectProcessor() {
    @Override
    public void processFolder(org.machanism.machai.project.layout.ProjectLayout project) {
        System.out.println(project.getProjectDir());
    }
};
processor.scanFolder(repositoryRoot);
